// Après validation – documents à ajouter au RAG : le texte VALIDÉ par le soignant (relu, éventuellement corrigé),
// lu dans la table des validations (source de vérité), jamais le texte brut de l'IA ni un texte reçu de l'extérieur.
// Un rapport validé est indexé avec la source « Rapport validé » et le type « rapport_valide » : les nouveaux rapports
// SBAR ne le relisent pas comme un fait (voir « chercher »), il reste consultable par le Mode B.
const fmt = (d) => {
  const p = new Intl.DateTimeFormat('fr-FR', { timeZone: 'Europe/Berlin', day: '2-digit', month: '2-digit', hour: '2-digit', minute: '2-digit', hourCycle: 'h23' }).formatToParts(new Date(d));
  const g = (t) => p.find((x) => x.type === t).value;
  return `${g('day')}.${g('month')}. ${g('hour')}h${g('minute')}`;
};
const lignes = $input.all().map((i) => i.json).filter((r) => r.validation_id);
return lignes.map((r) => ({
  json: {
    collection: 'patients',
    texte: r.texte,
    titre: `Rapport de garde validé (SBAR), ${fmt(r.valide_le)}`,
    source: 'validation',
    source_label: 'Rapport validé',
    source_ref: `validation-${r.validation_id}`,
    type: 'rapport_valide',
    patient_id: r.patient_id,
    chambre: r.chambre,
    patient_label: `${r.civilite} ${r.prenom} ${r.nom} (chambre ${r.chambre})`,
    date: new Date(r.valide_le).toISOString(),
  },
}));

// Après validation – message de transmission à l'équipe suivante : les textes VALIDÉS (lus dans la table des
// validations), avec leurs sources et le nom du soignant qui les a validés.
const DESTINATAIRE = 'equipe-suivante@sonnenhof.example.test';
const entree = $('Entrée').first().json;
const rapports = $('Rapports validés').all().map((i) => i.json).filter((r) => r.validation_id);
if (!rapports.length) throw new Error('Aucun rapport validé à transmettre.');

const fmt = (d) => {
  const p = new Intl.DateTimeFormat('fr-FR', { timeZone: 'Europe/Berlin', day: '2-digit', month: '2-digit', year: 'numeric', hour: '2-digit', minute: '2-digit', hourCycle: 'h23' }).formatToParts(new Date(d));
  const g = (t) => p.find((x) => x.type === t).value;
  return { jour: `${g('day')}.${g('month')}.${g('year')}`, heure: `${g('hour')}h${g('minute')}` };
};
const portee = entree.portee === 'etage' ? 'etage' : 'resident';
const etage = portee === 'etage' ? Number(entree.etage) : null;
const maintenant = fmt(new Date());
const sujet = portee === 'etage'
  ? `Transmission de garde – étage ${etage} – ${maintenant.jour} ${maintenant.heure}`
  : `Transmission de garde – chambre ${rapports[0].chambre} (${rapports[0].civilite} ${rapports[0].nom}) – ${maintenant.jour} ${maintenant.heure}`;

const blocs = rapports.map((r) => {
  const v = fmt(r.valide_le);
  const sources = (Array.isArray(r.sources) ? r.sources : []).map((s) => `[${s}]`).join(' ');
  return [
    `=== Chambre ${r.chambre} – ${r.civilite} ${r.prenom} ${r.nom} (étage ${r.etage}) ===`,
    r.texte.trim(),
    `Sources : ${sources || 'aucune'}`,
    `Validé par ${r.valide_par} le ${v.jour} à ${v.heure}.`,
  ].join('\n');
});
const texte = [
  sujet,
  '',
  'Ce message reprend les rapports de garde des 12 dernières heures, relus et validés par un soignant. Ils ont été rédigés avec l\'aide d\'un assistant IA pour les équipes soignantes ; en cas de doute, se reporter au dossier de soins.',
  '',
  blocs.join('\n\n'),
].join('\n');

return [
  {
    json: {
      sujet,
      texte,
      destinataire: DESTINATAIRE,
      portee,
      etage,
      patient_ids: rapports.map((r) => r.patient_id),
      validation_ids: rapports.map((r) => r.validation_id),
      mailpit: {
        From: { Email: 'transmission@sonnenhof.example.test', Name: 'AI-Care – Transmission de garde' },
        To: [{ Email: DESTINATAIRE, Name: 'Équipe suivante' }],
        Subject: sujet,
        Text: texte,
      },
    },
  },
];

// Après validation – résultat : combien de rapports ajoutés au RAG, et la transmission (envoyée ou en échec).
const m = $('Message de transmission').first().json;
const envoi = $('Envoyer (Mailpit)').first().json;
const note = $('Noter la transmission').first().json;
const rag = $('Indexer (RAG)').first().json ?? {};
const echec = Boolean(envoi?.error);
return [
  {
    json: {
      rag: { ajoutes: rag.morceaux_indexes ?? 0, ignores_deja_importes: rag.ignores_deja_importes ?? 0 },
      transmission: {
        id: note.id,
        statut: echec ? 'echec' : 'envoye',
        destinataire: m.destinataire,
        sujet: m.sujet,
        portee: m.portee,
        nb_rapports: m.validation_ids.length,
      },
      evenements_journal: [
        {
          evenement: 'ajout_rag',
          patient_id: m.patient_ids.length === 1 ? m.patient_ids[0] : null,
          mode: 'a',
          action: 'generer_sbar',
          details: { validations: m.validation_ids, morceaux: rag.morceaux_indexes ?? 0 },
        },
        {
          evenement: 'transmission',
          patient_id: m.patient_ids.length === 1 ? m.patient_ids[0] : null,
          mode: 'a',
          action: 'generer_sbar',
          details: { transmission_id: note.id, statut: echec ? 'echec' : 'envoye', portee: m.portee, etage: m.etage, validations: m.validation_ids },
        },
      ],
    },
  },
];

// Après validation – sortie du sous-workflow (sans les événements de journal).
const { evenements_journal, ...resultat } = $('Résumé').first().json;
return [{ json: resultat }];
